import{_ as t,l as d,o as r,c as n,v as o,p as i,x as e,d as s,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Pollard rho","description":"","frontmatter":{"title":"Pollard rho","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pollard-rho.md","filePath":"cs/pollard-rho.md","lastUpdated":1789023840000}'),c={name:"cs/pollard-rho.md"};function _(f,a,m,u,x,P){const l=d("Mermaid");return r(),n("div",null,[a[1]||(a[1]=o('<h1 id="pollard-rho" tabindex="-1">Pollard rho <a class="header-anchor" href="#pollard-rho" aria-label="Permalink to &quot;Pollard rho&quot;">​</a></h1><div class="epigraph"><p>伪随机迭代在模 $n$ 上走，Floyd 判圈；$\\gcd(|x-y|,n)$ 给出因子，期望 $\\tilde O(n^{1/4})$ 级。</p><footer>—— 据 Pollard, A Monte Carlo Method for Factorization, 1975；CLRS 第 31.9 节整理</footer></div><p>上一课<a href="/cs/bsgs">BSGS</a>在已知阶的群上根号搜对数。本课 \\(n\\) 合数，求非平凡因子。试除 \\(O(\\sqrt n)\\)。缺口是 Pollard rho：生日悖论在因子 \\(p\\) 的环上碰撞。不重写 Miller–Rabin 素性。后课 Lucas 换组合数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n=pq\\) 时，映射 \\(f(x)=x^2+c\\bmod n\\) 在模 \\(p\\) 下进入短环。Floyd：龟兔 \\(x,f(x)\\) 与 \\(f(f)\\)。\\(\\gcd(|x_i-x_j|,n)\\) 非 1 非 \\(n\\) 则因子。期望时间约 \\(O(n^{1/4})\\)（对最小素因子 \\(p\\) 为 \\(O(\\sqrt p)\\)）。失败换 \\(c\\)。</p><p>Brent 变体少算 \\(f\\)。Pollard \\(p-1\\) 是另一算法（光滑阶），点名。</p><h3 id="不是素性测试" tabindex="-1">不是素性测试 <a class="header-anchor" href="#不是素性测试" aria-label="Permalink to &quot;不是素性测试&quot;">​</a></h3><p>rho 假定 \\(n\\) 合数。先 Miller–Rabin。素数上 gcd 总是 1 或 \\(n\\)。不要对素数跑 rho 当分解。</p><p><span class="marginnote">Pollard 1975。CLRS 31.9。二次筛、NFS 分解大整数，本课 rho 适合 60–80 位因子量级直觉。后课 Lucas 定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>随机 \\(x_0,c\\)。Floyd 循环。每次 gcd。得到因子后递归分解。完全平方先开方。</p>',11)),(r(),i(p,null,{default:e(()=>[h(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22x%E2%86%90x%C2%B2%2Bc%20mod%20n%22%5D%20--%3E%20FLOYD%5B%22%E9%BE%9F%E5%85%94%22%5D%0A%20%20FLOYD%20--%3E%20G%5B%22gcd(%7Cx-y%7C%2C%20n)%22%5D%0A%20%20G%20--%3E%20FAC%5B%22%E9%9D%9E%E5%B9%B3%E5%87%A1%E5%9B%A0%E5%AD%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>离散对数的 rho 用函数在陪集上，点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>生日：模 \\(p\\) 约 \\(\\sqrt p\\) 步碰撞，碰撞差是 \\(p\\) 的倍数。Floyd 空间 \\(O(1)\\)。与 BSGS：对数要哈希表；rho 分解用 gcd。随机化 Las Vegas/Monte Carlo 分类后课再钉。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 NFS。不写椭圆曲线分解（Lenstra ECM）全文。后课默认：中等因子用 rho。下一课 Lucas 定理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(f\\) 迭代 + Floyd + gcd 出因子。</li><li>期望依赖最小素因子的根号。</li><li>先确认合数。</li><li>出处：Pollard, 1975；CLRS 第 31.9 节。</li></ul>',7))])}const q=t(c,[["render",_]]);export{S as __pageData,q as default};
